import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx')
task_sheet = wb['Task']
data_sheet = wb['Data']

def scan_sheet(sheet, name):
    print(f"--- Scanning {name} ---")
    for r in range(1, 25):
        row_vals = []
        for c in range(1, 20):
            val = sheet.cell(row=r, column=c).value
            if val is not None:
                row_vals.append(f"({r},{c}):{val}")
        if row_vals:
            print(f"Row {r}: {row_vals}")

scan_sheet(task_sheet, "Task")
scan_sheet(data_sheet, "Data")
